from enum import StrEnum

class Role(StrEnum):
    OPERATOR = "operator"
    SUPERVISOR = "supervisor"
    ADMIN = "admin"

def role_for(user):
    if not getattr(user, "is_authenticated", False):
        return None
    value = getattr(getattr(user, "profile", None), "role", None)
    try:
        return Role(value)
    except (ValueError, TypeError):
        return None

def can_configure(user):
    return role_for(user) in {Role.SUPERVISOR, Role.ADMIN}

