@transaction.atomic
def store_reading(*, sensor, event_key, occurred_at, value):
    reading, created = Reading.objects.get_or_create(
        event_key=event_key,
        defaults={"sensor": sensor, "occurred_at": occurred_at, "value": value},
    )
    if not created and (reading.sensor_id != sensor.pk or reading.value != value):
        raise ValueError("La clave ya se usó para otro contenido.")
    return reading, created

