from math import ceil

def sample_uniform(rows, max_points=2000):
    if max_points < 2:
        raise ValueError("max_points debe ser >= 2")
    if len(rows) <= max_points:
        return list(rows)
    step = ceil((len(rows) - 1) / (max_points - 1))
    sampled = list(rows[::step])
    if sampled[-1] is not rows[-1]:
        sampled.append(rows[-1])
    return sampled

